namespace fs=std::filesystem;
static void req(bool v,const std::string&m){if(!v)throw std::runtime_error(m);}
static std::vector<uint8_t>read(const fs::path&p){std::ifstream f(p,std::ios::binary);req(bool(f),"read "+p.string());return {std::istreambuf_iterator<char>(f),{}};}
static NSString*hash(const fs::path&p){auto b=read(p);unsigned char d[CC_SHA256_DIGEST_LENGTH];CC_SHA256(b.data(),(CC_LONG)b.size(),d);NSMutableString*s=[NSMutableString string];for(auto v:d)[s appendFormat:@"%02x",v];return s;}
static NSDictionary*loadJSON(const fs::path&p){auto d=[NSData dataWithContentsOfFile:@(p.c_str())];NSError*error=nil;id obj=[NSJSONSerialization JSONObjectWithData:d options:0 error:&error];req([obj isKindOfClass:NSDictionary.class],"JSON "+p.string());return obj;}
static void json(const fs::path&p,id value){NSError*error=nil;auto d=[NSJSONSerialization dataWithJSONObject:value options:NSJSONWritingPrettyPrinted error:&error];req(d&&[d writeToFile:@(p.c_str()) atomically:YES],"write JSON");}
static void save(const fs::path&p,id<MTLBuffer>b){fs::create_directories(p.parent_path());std::ofstream f(p,std::ios::binary);f.write((char*)b.contents,b.length);req(bool(f),"save output");}
static id<MTLBuffer>buf(id<MTLDevice>d,const fs::path&p,size_t n){auto b=read(p);req(b.size()==n,"bad input extent");return[d newBufferWithBytes:b.data() length:n options:MTLResourceStorageModeShared];}
static NSDictionary*power(){return @{@"thermal":@((int)NSProcessInfo.processInfo.thermalState),@"low_power":@(NSProcessInfo.processInfo.lowPowerModeEnabled),@"battery_level":@(UIDevice.currentDevice.batteryLevel),@"battery_state":@((int)UIDevice.currentDevice.batteryState),@"uptime_s":@(NSProcessInfo.processInfo.systemUptime)};}
class StockQ{
 ggml_metal_device_t dev_=nullptr;ggml_context*ctx_=nullptr;ggml_metal_pipeline_with_params p_{};
public:
 StockQ(){dev_=ggml_metal_device_init(0,1);req(dev_,"Metal device");ctx_=ggml_init({4*ggml_tensor_overhead(),nullptr,true});req(ctx_,"ggml context");auto w=ggml_new_tensor_2d(ctx_,GGML_TYPE_TQ2_0,2560,2560);auto x=ggml_new_tensor_2d(ctx_,GGML_TYPE_F32,2560,1);auto y=ggml_mul_mat(ctx_,w,x);p_=ggml_metal_library_get_pipeline_mul_mv(ggml_metal_device_get_library(dev_),y,false,false);req(p_.pipeline&&p_.nr0==4&&p_.nsg==2,"actual stock Q specialization changed");}
 ~StockQ(){if(ctx_)ggml_free(ctx_);if(dev_)ggml_metal_device_free(dev_);}
 id<MTLDevice>device(){return(__bridge id<MTLDevice>)ggml_metal_device_get_obj(dev_);}id<MTLCommandQueue>queue(){return(__bridge id<MTLCommandQueue>)ggml_metal_device_get_queue(dev_);}
 void encode(ggml_metal_encoder_t e,id<MTLBuffer>w,id<MTLBuffer>x,id<MTLBuffer>y,bool trace){ggml_metal_kargs_mul_mv a={2560,2560,1,66,660,1689600,1689600,2560,1,1,4,10240,10240,10240,2560,1,4,1,1,0.0f};ggml_metal_encoder_set_pipeline(e,p_);ggml_metal_encoder_set_bytes(e,&a,sizeof(a),0);auto bind=[](id<MTLBuffer>b){return ggml_metal_buffer_id{(__bridge void*)b,0};};ggml_metal_encoder_set_buffer(e,bind(w),1);ggml_metal_encoder_set_buffer(e,bind(x),2);ggml_metal_encoder_set_buffer(e,bind(y),3);ggml_metal_encoder_set_buffer(e,bind(y),4);ggml_metal_encoder_set_buffer(e,bind(x),5);ggml_metal_encoder_set_threadgroup_memory_size(e,p_.smem,0);ggml_metal_encoder_dispatch_threadgroups(e,320,1,1,32,2,1);if(trace)ggml_metal_encoder_trace_bitnet(e,p_,"q-operator-stock",1,320,1,1,2);}
};
static id<MTLComputePipelineState>pipeline(id<MTLDevice>d,const fs::path&p){NSError*error=nil;auto lib=[d newLibraryWithURL:[NSURL fileURLWithPath:@(p.c_str())] error:&error];req(lib,"load candidate library");auto f=[lib newFunctionWithName:@"tq2_0_matvec_poc_c8x2"];req(f,"candidate symbol");auto result=[d newComputePipelineStateWithFunction:f error:&error];req(result&&result.threadExecutionWidth==32&&result.maxTotalThreadsPerThreadgroup>=64,"candidate PSO resources");return result;}
struct Engine{StockQ stock;id<MTLComputePipelineState>c8,q4;Engine(const fs::path&root):c8(pipeline(stock.device(),root/"q-c8x2.metallib")),q4(pipeline(stock.device(),root/"q-stock4x1.metallib")){}
 double dispatch(const std::string&route,id<MTLBuffer>w,id<MTLBuffer>x,id<MTLBuffer>y,bool trace=false){@autoreleasepool{auto cmd=[stock.queue() commandBuffer];cmd.label=@(("Qcur0-operator-"+route).c_str());auto e=ggml_metal_encoder_init((__bridge void*)cmd,false);req(e,"encoder");if(route=="S")stock.encode(e,w,x,y,trace);else{auto raw=(__bridge id<MTLComputeCommandEncoder>)ggml_metal_encoder_get_obj(e);[raw setComputePipelineState:route=="C8"?c8:q4];[raw setBuffer:w offset:0 atIndex:0];[raw setBuffer:x offset:0 atIndex:1];[raw setBuffer:y offset:0 atIndex:2];[raw dispatchThreadgroups:MTLSizeMake(route=="C8"?160:640,1,1) threadsPerThreadgroup:MTLSizeMake(32,route=="C8"?2:1,1)];}ggml_metal_encoder_end_encoding(e);ggml_metal_encoder_free(e);[cmd commit];[cmd waitUntilCompleted];req(cmd.status==MTLCommandBufferStatusCompleted&&!cmd.error,"GPU command failed");double us=(cmd.GPUEndTime-cmd.GPUStartTime)*1e6;req(std::isfinite(us)&&us>0,"invalid GPU command-buffer elapsed");return us;}}
};
// Same logical unpack/FP64 accumulation as the preserved stage2 reference.cpp.
static std::array<double,2560>reference(const std::vector<uint8_t>&w,const float*x){std::array<double,2560>out{};for(int row=0;row<2560;++row){double sum=0;for(int b=0;b<10;++b){auto block=w.data()+(row*10+b)*66;uint16_t bits=uint16_t(block[64])|(uint16_t(block[65])<<8);_Float16 h;std::memcpy(&h,&bits,2);double scale=double(h);req(std::isfinite(scale),"nonfinite scale");const float*v=x+b*256;for(int half=0;half<2;++half)for(int plane=0;plane<4;++plane)for(int j=0;j<32;++j){int q=(block[32*half+j]>>(2*plane))&3;sum+=(q-1)*scale* *v++;}}out[row]=sum;}return out;}
struct Metric{size_t failed=0,nonfinite=0,bits=0;double maxabs=0,relativeL2=0;};
static Metric compare(id<MTLBuffer>y,const std::array<double,2560>&r,const float*stock,int step,const std::string&route,std::ofstream&rows){Metric m;double error2=0,ref2=0;auto a=(const float*)y.contents;for(int i=0;i<2560;++i){double e=std::abs(double(a[i])-r[i]),tol=2e-4+2e-5*std::abs(r[i]);bool finite=std::isfinite(a[i])&&std::isfinite(r[i]);m.nonfinite+=!finite;m.failed+=!finite||e>tol;m.maxabs=std::max(m.maxabs,e);m.bits+=std::memcmp(a+i,stock+i,4)!=0;error2+=e*e;ref2+=r[i]*r[i];rows<<step<<','<<route<<','<<i<<','<<r[i]<<','<<a[i]<<','<<e<<','<<tol<<','<<e/tol<<','<<(!finite||e>tol)<<','<<!finite<<'\n';}m.relativeL2=std::sqrt(error2/ref2);return m;}
static double quantile(std::vector<double>x,double p){std::sort(x.begin(),x.end());double k=(x.size()-1)*p;size_t lo=(size_t)k,hi=(size_t)std::ceil(k);return x[lo]+(x[hi]-x[lo])*(k-lo);}
static int run(const fs::path&fixture,const fs::path&shaders,const fs::path&out,const std::string&mode){req(mode=="verify"||mode=="benchmark","bad Q operator mode");auto manifest=loadJSON(fixture/"MANIFEST.json");req([manifest[@"model_sha256"]isEqual:@"52257df879ab4366d97228e7bda94a9a3c6a9065ec44e7879a8b87d54e568cd2"],"model SHA identity");NSMutableDictionary*inputs=[NSMutableDictionary dictionary];for(int step:{1,16,32})for(NSString*name in @[@"w.tq2",@"x.f32",@"y.f32"]){auto file=fixture/("step-"+std::to_string(step))/name.UTF8String;NSString*h=hash(file);req([h isEqual:manifest[@"fixtures"][@(std::to_string(step).c_str())][name][@"sha256"]],"phone fixture hash mismatch");inputs[@(file.c_str())]=h;}NSMutableDictionary*libs=[NSMutableDictionary dictionary];for(NSString*route in @[@"C8",@"Q4"]){NSDictionary*entry=manifest[@"libraries"][route];auto file=shaders/[(NSString*)entry[@"file"] UTF8String];NSString*h=hash(file);req([h isEqual:entry[@"sha256"]],"Q library hash mismatch");libs[route]=h;}
 if(mode=="verify"){req(!fs::exists(out),"refuse Q verification overwrite");fs::create_directories(out);}else{req(fs::is_regular_file(out/"qualification.json"),"Q verification gate missing");auto gate=loadJSON(out/"qualification.json");req([gate[@"local_fp64_pass"]boolValue]&&[gate[@"inputs"]isEqual:inputs]&&[gate[@"libraries"]isEqual:libs],"Q timing gate mismatch");req(!fs::exists(out/"performance"),"refuse Q timing overwrite");fs::create_directories(out/"performance");}
 Engine engine(shaders);auto device=engine.stock.device();req([device.name isEqual:@"Apple A16 GPU"],"requires A16");
 if(mode=="verify"){std::ofstream rows(out/"rows.csv");rows<<std::setprecision(17)<<"step,route,index,reference,actual,abs_error,tolerance,error_over_tolerance,failed,nonfinite\n";NSMutableArray*cases=[NSMutableArray array];bool pass=true;for(int step:{1,16,32}){auto folder=fixture/("step-"+std::to_string(step));auto w=buf(device,folder/"w.tq2",1689600),x=buf(device,folder/"x.f32",10240);auto wr=read(folder/"w.tq2");auto ref=reference(wr,(float*)x.contents);id<MTLBuffer>ys=[device newBufferWithLength:10240 options:MTLResourceStorageModeShared];for(int i=0;i<2560;++i)((float*)ys.contents)[i]=NAN;engine.dispatch("S",w,x,ys,true);for(auto route:{"S","C8","Q4"}){auto y=[device newBufferWithLength:10240 options:MTLResourceStorageModeShared];for(int i=0;i<2560;++i)((float*)y.contents)[i]=NAN;engine.dispatch(route,w,x,y,route==std::string("S"));auto m=compare(y,ref,(float*)ys.contents,step,route,rows);pass&=!m.failed&&!m.nonfinite;save(out/("step-"+std::to_string(step))/(std::string(route)+".f32"),y);[cases addObject:@{@"step":@(step),@"route":@(route),@"rows":@2560,@"failed_rows":@(m.failed),@"nonfinite_rows":@(m.nonfinite),@"stock_bit_different_rows":@(m.bits),@"max_abs":@(m.maxabs),@"relative_L2":@(m.relativeL2),@"GPU_completed":@YES}];}}rows.close();NSDictionary*result=@{@"analysis_completed":@YES,@"local_fp64_pass":@(pass),@"model_output_pass":[NSNull null],@"model_quality_tested":@NO,@"cases":cases,@"inputs":inputs,@"libraries":libs,@"device":device.name,@"scope":@"isolated actual phone Qcur-0 W/X at steps1,16,32; actual embedded stockPSO vs C8 and stock4x1",@"tolerance":@{@"abs":@(2e-4),@"relative":@(2e-5)}};json(out/"qualification.json",result);return pass?0:1;}
 auto f=fixture/"step-16";auto w=buf(device,f/"w.tq2",1689600),x=buf(device,f/"x.f32",10240),yA=[device newBufferWithLength:10240 options:MTLResourceStorageModeShared],yB=[device newBufferWithLength:10240 options:MTLResourceStorageModeShared];std::ofstream csv(out/"performance/samples.csv");csv<<std::setprecision(17)<<"round,comparison,pair,order,first_route,second_route,first_us,second_us,second_minus_first_us\n";NSMutableArray*groups=[NSMutableArray array];for(int rr=1;rr<=3;++rr){std::vector<std::string>comparisons={"AA","SQ","CQ"};std::rotate(comparisons.begin(),comparisons.begin()+(rr-1),comparisons.end());for(auto&comparison:comparisons){std::string a=comparison=="CQ"?"C8":"S",b=comparison=="AA"?"S":"Q4";NSDictionary*before=power();for(int i=0;i<30;++i){engine.dispatch(a,w,x,yA);engine.dispatch(b,w,x,yB);}std::vector<double>av,bv,dv;int wins=0;for(int i=0;i<201;++i){bool ab=i%4==0||i%4==3;if(rr%2==0)ab=!ab;double aa,bb;if(ab){aa=engine.dispatch(a,w,x,yA);bb=engine.dispatch(b,w,x,yB);}else{bb=engine.dispatch(b,w,x,yB);aa=engine.dispatch(a,w,x,yA);}av.push_back(aa);bv.push_back(bb);dv.push_back(bb-aa);wins+=bb<aa;csv<<rr<<','<<comparison<<','<<i<<','<<(ab?"AB":"BA")<<','<<a<<','<<b<<','<<aa<<','<<bb<<','<<bb-aa<<'\n';}[groups addObject:@{@"round":@(rr),@"comparison":@(comparison.c_str()),@"first_route":@(a.c_str()),@"second_route":@(b.c_str()),@"first_p50_us":@(quantile(av,.5)),@"first_p95_us":@(quantile(av,.95)),@"second_p50_us":@(quantile(bv,.5)),@"second_p95_us":@(quantile(bv,.95)),@"paired_second_minus_first_p50_us":@(quantile(dv,.5)),@"second_wins":@(wins),@"pairs":@201,@"before":before,@"after":power()}];}}csv.close();json(out/"performance/summary.json",@{@"groups":groups,@"inputs":inputs,@"libraries":libs,@"capture":@NO,@"diagnostic_readback":@NO,@"single_dispatch_per_command_buffer":@YES,@"metric":@"(GPUEndTime-GPUStartTime)*1e6 after completion; GPU command-buffer elapsed microseconds",@"scope":@"single Qcur-0 operator, not model throughput"});return 0;
}
}
extern "C" int bitnet_run_iphone_q(const char*f,const char*s,const char*o,const char*m){@autoreleasepool{try{return bitnet_iphone_q::run(f,s,o,m);}catch(const std::exception&e){std::fprintf(stderr,"BITNET_IPHONE_Q_ERROR %s\n",e.what());return 1;}}}
